svg.script:
//!export-start
let _pn_value = 0;
let _pn_min = 0;
let _pn_max = 100;
let _pb_hasSetpoint = false;
let _pn_setpoint = 0;
let _ps_type = 'filled';
let _pb_labels = true;
let _ps_priority = 'regular';
let _pb_off = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.value = toNum(_pn_value);
    el.minValue = toNum(_pn_min);
    el.maxValue = toNum(_pn_max);
    el.type = String(_ps_type);
    el.showLabels = toBool(_pb_labels);
    el.priority = String(_ps_priority);
    el.setpoint = toBool(_pb_hasSetpoint) ? toNum(_pn_setpoint) : undefined;
    el.state = toBool(_pb_off) ? 'off' : 'active';
}

function putValue(id, value) {
    if (id === '_pn_value') { _pn_value = toNum(value); }
    if (id === '_pn_min') { _pn_min = toNum(value); }
    if (id === '_pn_max') { _pn_max = toNum(value); }
    if (id === '_pb_hasSetpoint') { _pb_hasSetpoint = toBool(value); }
    if (id === '_pn_setpoint') { _pn_setpoint = toNum(value); }
    if (id === '_ps_type') { _ps_type = String(value); }
    if (id === '_pb_labels') { _pb_labels = toBool(value); }
    if (id === '_ps_priority') { _ps_priority = String(value); }
    if (id === '_pb_off') { _pb_off = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 192;
    var h = parseFloat(root.getAttribute('height')) || 192;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);
    el.style.width = w + 'px';
    el.style.height = h + 'px';
}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

apply();
